SELECT CAST(COUNT(DISTINCT CASE WHEN p.dischtime - p.admittime <= 30 THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN EXTRACT(YEAR FROM p.admittime) BETWEEN 2015 AND 2016 THEN p.subject_id END), 0) AS readmission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM p.admittime) BETWEEN 2015 AND 2016 AND a.hadm_id IN (SELECT hadm_id FROM procedures_icd WHERE icd_code = '47017');